import type { ConfigManager } from './ConfigManager';
import {
  getRequestAuthContext,
  updateRequestAuthContext,
} from './RequestAuthContext';

interface AccountTokens {
  token: string;
  refreshToken?: string;
}

export const captureAuthUpdate = (
  config: ConfigManager,
): ((tokens: AccountTokens) => void) => {
  const requestContext = getRequestAuthContext();
  const expectedGeneration = requestContext
    ? undefined
    : config.getAuthorizationGeneration();
  const email = config.getEmail() ?? '';
  const userId = config.getUserId();
  return ({ token, refreshToken }) => {
    if (requestContext) {
      updateRequestAuthContext({ token, refreshToken });
      return;
    }
    config.setAuth(token, email, refreshToken, userId, { expectedGeneration });
  };
};
